CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE towns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, role text NOT NULL CHECK(role IN ('customer','operator','owner','admin')), disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE partners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, town_id uuid NOT NULL REFERENCES towns(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended')), paused boolean NOT NULL DEFAULT false, preparation_minutes int NOT NULL DEFAULT 25 CHECK(preparation_minutes BETWEEN 5 AND 180), collection boolean NOT NULL DEFAULT true, delivery_fee int NOT NULL DEFAULT 200 CHECK(delivery_fee>=0), delivery_postcodes text[] NOT NULL DEFAULT '{}', stripe_account text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(user_id uuid NOT NULL REFERENCES users(id), partner_id uuid NOT NULL REFERENCES partners(id), PRIMARY KEY(user_id,partner_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE auth_challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, code_hash text NOT NULL, attempts int NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE INDEX auth_email_idx ON auth_challenges(email,expires_at);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), partner_id uuid REFERENCES partners(id), action text NOT NULL, subject text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fee_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partners(id), fixed_fee int NOT NULL CHECK(fixed_fee>=0), basis_points int NOT NULL DEFAULT 0 CHECK(basis_points BETWEEN 0 AND 10000), minimum_fee int NOT NULL DEFAULT 0 CHECK(minimum_fee>=0), maximum_fee int CHECK(maximum_fee>=minimum_fee), service_fee int NOT NULL DEFAULT 100 CHECK(service_fee>=0), subscription_fee int NOT NULL DEFAULT 0 CHECK(subscription_fee>=0), vat_basis_points int NOT NULL DEFAULT 0 CHECK(vat_basis_points BETWEEN 0 AND 10000), tax_confirmed boolean NOT NULL DEFAULT false, approved_by uuid NOT NULL REFERENCES users(id), effective_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX fee_policy_partner_idx ON fee_policies(partner_id,effective_at DESC);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partners(id), category text NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', price int NOT NULL CHECK(price>0), allergens text[] NOT NULL DEFAULT '{}', available boolean NOT NULL DEFAULT true, UNIQUE(id,partner_id));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partners(id), customer_id uuid REFERENCES users(id), tracking_hash text NOT NULL, request_key text NOT NULL UNIQUE, request_hash text NOT NULL, customer_name text NOT NULL, customer_email text NOT NULL, fulfilment text NOT NULL CHECK(fulfilment IN ('collection','delivery')), address jsonb, scheduled_at timestamptz, status text NOT NULL CHECK(status IN ('awaiting_payment','awaiting_acceptance','accepted','rejected','preparing','ready','out_for_delivery','completed','cancelled','refund_pending','refunded')), payment_method text NOT NULL CHECK(payment_method IN ('cash','card')), payment_state text NOT NULL CHECK(payment_state IN ('pending','authorised','captured','failed','refunded','partially_refunded')), subtotal int NOT NULL CHECK(subtotal>=0), delivery_fee int NOT NULL CHECK(delivery_fee>=0), service_fee int NOT NULL CHECK(service_fee>=0), partner_fee int NOT NULL CHECK(partner_fee>=0), total int NOT NULL CHECK(total=subtotal+delivery_fee+service_fee), pricing_snapshot jsonb NOT NULL, refunded_amount int NOT NULL DEFAULT 0 CHECK(refunded_amount>=0 AND refunded_amount<=total), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(id,partner_id));
CREATE INDEX orders_partner_idx ON orders(partner_id,created_at DESC);
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), product_id uuid NOT NULL REFERENCES products(id), name text NOT NULL, quantity int NOT NULL CHECK(quantity BETWEEN 1 AND 50), unit_price int NOT NULL CHECK(unit_price>0));
CREATE TABLE order_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), status text NOT NULL, reason text, actor_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), provider_id text UNIQUE, stripe_account text, state text NOT NULL, amount int NOT NULL CHECK(amount>0), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events(provider_id text PRIMARY KEY, type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), request_key text NOT NULL UNIQUE, amount int NOT NULL CHECK(amount>0), provider_id text UNIQUE, status text NOT NULL CHECK(status IN ('pending','succeeded','failed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES partners(id), order_id uuid REFERENCES orders(id), reference text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('partner_fee','cash_service_fee','fee_credit','subscription','adjustment')), amount int NOT NULL, vat_basis_points int NOT NULL CHECK(vat_basis_points BETWEEN 0 AND 10000), tax_confirmed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ledger_partner_idx ON ledger_entries(partner_id,created_at);
CREATE SEQUENCE invoice_number_seq;
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text NOT NULL UNIQUE DEFAULT ('TNE-'||lpad(nextval('invoice_number_seq')::text,8,'0')), partner_id uuid NOT NULL REFERENCES partners(id), period_start date NOT NULL, period_end date NOT NULL CHECK(period_end=period_start+7), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','paid','void')), net int NOT NULL, vat int NOT NULL, total int NOT NULL CHECK(total=net+vat), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(partner_id,period_start));
CREATE TABLE invoice_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), ledger_id uuid NOT NULL UNIQUE REFERENCES ledger_entries(id), description text NOT NULL, net int NOT NULL, vat int NOT NULL);
CREATE TABLE reconciliation_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id text NOT NULL UNIQUE, order_id uuid NOT NULL REFERENCES orders(id), amount int NOT NULL, state text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid REFERENCES orders(id), recipient text NOT NULL, kind text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', delivered_at timestamptz, attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,kind));
CREATE TABLE support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid REFERENCES partners(id), customer_id uuid REFERENCES users(id), subject text NOT NULL, category text NOT NULL DEFAULT 'general', priority text NOT NULL DEFAULT 'normal', status text NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES support_tickets(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations(name text PRIMARY KEY, enabled boolean NOT NULL DEFAULT false);
INSERT INTO integrations(name) VALUES ('xero'),('quickbooks'),('apple_maps'),('google_places'),('osm') ON CONFLICT DO NOTHING;
CREATE TABLE platform_settings(key text PRIMARY KEY, value jsonb NOT NULL);
INSERT INTO platform_settings VALUES ('loyalty','{"enabled":false}'),('invoice_collection','{"enabled":false}');
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable financial or audit record'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER invoice_lines_immutable BEFORE UPDATE OR DELETE ON invoice_lines FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER policy_immutable BEFORE UPDATE OR DELETE ON fee_policies FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION require_partner_pricing() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='active' AND NOT EXISTS(SELECT 1 FROM fee_policies WHERE partner_id=NEW.id AND effective_at<=now()) THEN RAISE EXCEPTION 'approved explicit pricing required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER partner_activation BEFORE INSERT OR UPDATE ON partners FOR EACH ROW EXECUTE FUNCTION require_partner_pricing();
